import React from 'react';
import { Link } from 'react-router-dom';
import { FaHome, FaShoppingCart, FaCashRegister } from 'react-icons/fa';

function Navbar() {
  return (
    <nav style={{ display: 'flex', gap: '2rem', padding: '1rem', background: '#eee' }}>
      <Link to="/" style={{ display: 'flex', alignItems: 'center', textDecoration: 'none', color: 'black' }}>
        <FaHome style={{ marginRight: '0.5rem' }} />
        Home
      </Link>
      <Link to="/cart" style={{ display: 'flex', alignItems: 'center', textDecoration: 'none', color: 'black' }}>
        <FaShoppingCart style={{ marginRight: '0.5rem' }} />
        Cart
      </Link>
      <Link to="/checkout" style={{ display: 'flex', alignItems: 'center', textDecoration: 'none', color: 'black' }}>
        <FaCashRegister style={{ marginRight: '0.5rem' }} />
        Checkout
      </Link>
    </nav>
  );
}

export default Navbar;
